import { readConfig } from '../src/config.js'; import { Queue } from '../src/queue/client.js'; import { JOB_TYPES, validateJob } from '../src/jobs/types.js';
const [type, ...args] = process.argv.slice(2); const value = (flag: string) => { const i = args.indexOf(flag); return i < 0 ? null : args[i + 1] || null; }; const parameters: Record<string, unknown> = {}; if (value('--candidate-id')) parameters.candidate_id = value('--candidate-id'); if (value('--run-id')) parameters.run_id = value('--run-id'); if (!JOB_TYPES.includes(type as any)) throw new Error(`Unsupported job type. Use ${JOB_TYPES.join(', ')}.`); validateJob(type, parameters); const queue = new Queue(readConfig()); const result = await queue.rpc('submit_pipeline_job', { p_job_type: type, p_parameters: parameters, p_source: 'cli', p_priority: Number(value('--priority') || 50), p_max_attempts: readConfig().maxAttempts }); console.log(JSON.stringify(result, null, 2));
